import {readFile,writeFile,appendFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const root='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925',oldAckFile=process.argv[2];
const ack=JSON.parse(await readFile(oldAckFile,'utf8')),config=JSON.parse(await readFile(ack.config_file,'utf8'));
const source=await readFile(ack.driver_file,'utf8'),sha=value=>createHash('sha256').update(value).digest('hex');
if(sha(source)!==ack.driver_sha256)throw new Error('Owned driver source changed');
const journalFile=ack.config_file.replace('parent-owned-nonsecret-bindings.json','FVI-CORE455-20261004-A-journal.jsonl');
const events=(await readFile(journalFile,'utf8')).trim().split('\n').map(JSON.parse);
const oldKey=config.run_tag+'.01.correct-staging';
const intent=events.findLast(e=>e.key===oldKey&&e.state==='intent');
const unresolved=events.filter(e=>e.state==='intent'&&!events.some(done=>done.key===e.key&&done.state==='completed'&&done.payload_sha256===e.payload_sha256));
if(unresolved.length!==1||unresolved[0]!==intent)throw new Error('Only the exact uncertain staging command may be superseded');
const clientConfig=JSON.parse(await readFile(`${root}/FVI-QA-TRANSPORT-PROD-20261001.json`,'utf8'));
const session=JSON.parse(await readFile(ack.sessions.checker,'utf8')).session;
const params=new URLSearchParams({select:'id,tenant_id,name,sides,rules,governance_state,governance_parent_id,updated_at',tenant_id:'eq.'+config.tenant_id,id:'eq.'+intent.request.id,limit:'2'});
const response=await fetch(`${clientConfig.apiUrl}/rest/v1/recon_definitions?${params}`,{headers:{apikey:clientConfig.anonKey,authorization:`Bearer ${session.access_token}`},redirect:'error',signal:AbortSignal.timeout(25000)});
const rows=await response.json();
if(!response.ok||!Array.isArray(rows)||rows.length!==1||rows[0].governance_state!=='staging_copy'||rows[0].name===intent.request.name||Date.parse(rows[0].updated_at)>=Date.parse(intent.at))throw new Error('Fresh unchanged staging-copy observation required');
const oldReadback=JSON.parse(await readFile(ack.config_file.replace('parent-owned-nonsecret-bindings.json','01-dq-repaired-readback.json'),'utf8'));
const stable=value=>JSON.stringify(value,(_,item)=>item&&typeof item==='object'&&!Array.isArray(item)?Object.fromEntries(Object.keys(item).sort().map(key=>[key,item[key]])):item);
if(rows[0].governance_parent_id!==oldReadback.definition_id||stable(rows[0].sides)!==stable(oldReadback.run.definition_snapshot.sides)||stable(rows[0].rules)!==stable(oldReadback.run.definition_snapshot.rules))throw new Error('Staging clone no longer matches approved pre-correction snapshot');
const before="  const revised = { ...draft, id: stageId, sides: resolved.outputs };\n  await t.once(tag + '.correct-staging', revised, () => t.app('maker', 'upsertRecon', revised));";
const after="  const currentStage = await one(t, 'recon_definitions', stageId);\n  requireThat(currentStage.governance_state === 'staging_copy' && currentStage.governance_parent_id === reconId, 'exact_staging_copy_required');\n  const revised = { ...draft, id: stageId, name: currentStage.name, sides: resolved.outputs };\n  await t.once(tag + '.correct-staging-preserve-generated-name', revised, () => t.app('maker', 'upsertRecon', revised));";
if(source.split(before).length!==2)throw new Error('Exact staging command boundary changed');
let next=source.replace(before,after);
const appMarker="    requireThat(response.ok && response.headers.get('content-type')?.includes('application/json'), `app_outcome_uncertain:${name}`);";
if(next.split(appMarker).length!==2)throw new Error('Actual application response boundary changed');
next=next.replace(appMarker,`    const responseFile = './LOCAL_USER/AppData/Local/FVI-QA-Private-20260925/' + config.run_tag + '-APP-RESPONSE-' + randomUUID() + '.json';
    const rawObservedBody = await response.clone().text();
    if (rawObservedBody.length > 1000000) throw new Error('bounded_application_response_exceeded');
    writeFileSync(responseFile, stable({at:new Date().toISOString(),actor:kind,operation:name,payload_sha256:hash(stable(data)),http:response.status,content_type:response.headers.get('content-type'),serialized:response.headers.get('x-tss-serialized'),rawBody:rawObservedBody}), {flag:'wx',mode:0o600});
    journal.record({key:'app-response',state:'observed',operation:name,payload_sha256:hash(stable(data)),http:response.status,receipt_file:responseFile});
${appMarker}`);
const tag=Date.now(),proof=`${root}/FVI-CORE455-STAGING-CORRECTED-COMMAND-${tag}.json`;
const transition={at:new Date().toISOString(),previousDriverSha256:ack.driver_sha256,nextDriverSha256:sha(next),change:'A distinct corrected staging save preserves actual generated staging name; originals and unknown outcome remain retained. Actual server responses now saved privately before decoder/guards.',oldKey,oldPayloadSha256:intent.payload_sha256,replacementKey:config.run_tag+'.01.correct-staging-preserve-generated-name',oldOutcome:'UNCONFIRMED_NOT_REPLAYED',currentStage:rows[0],businessWrites:0,noReplay:true};
await writeFile(proof,JSON.stringify(transition,null,2),{flag:'wx',mode:0o600});
await writeFile(`${root}/FVI-CORE455-DRIVER-PRE-STAGING-COMMAND-${tag}.mjs`,source,{flag:'wx',mode:0o600});
await writeFile(ack.driver_file,next);
await appendFile(journalFile,JSON.stringify({at:transition.at,key:oldKey,state:'superseded_uncertain_not_replayed',payload_sha256:intent.payload_sha256,replacement_key:transition.replacementKey,proof_file:proof})+'\n');
await appendFile(journalFile,JSON.stringify({key:'parent-observed-staging-input-contract-transition',state:'qualified',...transition,currentStage:undefined})+'\n');
const file=`${root}/FVI-CORE-GROUP1-RECON-F52-ACK-STAGING-CONTRACT-${tag}.json`;
await writeFile(file,JSON.stringify({...ack,driver_sha256:sha(next),source_contract_transition:transition,predecessor_ack:oldAckFile},null,2),{flag:'wx',mode:0o600});
console.log(JSON.stringify({ackFile:file,oldUnknownOutcomeRetained:true,distinctCorrectedCommand:true,businessWrites:0}));
